import json

with open('json/posts.json', 'r') as f:
    data = json.load(f)

# Search for exact title match
target_title = 'Computer Game Datasets'
exact_matches = []

for record in data['records']:
    title = record.get('Title')
    if title == target_title:
        exact_matches.append({
            'Id': record.get('Id'),
            'Title': title,
            'ViewCount': record.get('ViewCount'),
            'OwnerUserId': record.get('OwnerUserId')
        })

print(f"Found {len(exact_matches)} exact matches:")
for m in exact_matches:
    print(m)

# Also check for partial matches that might be close
if not exact_matches:
    print("\nSearching for close matches...")
    for record in data['records']:
        title = record.get('Title', '')
        if title and 'computer' in title.lower() and 'game' in title.lower():
            print(f"Close match: {title}")
